  {id="character_level",name="character level",syntax=".character level [$playername] [#level]",description="Set the level of character with $playername (or the selected if not name provided) by #numberoflevels Or +1 if no #numberoflevels provided). If #numberoflevels is omitted, the level will be increase by 1. If #numberoflevels is 0, the same level will be restarted. If no character is selected and name not provided, increase your level. Command can be used for offline character. All stats and dependent values recalculated. At level decrease talents can be reset if need. Also at level decrease equipped items with greater level requirement can be lost.",category="character",permissionId=283,permission="Command: character level",role="Administrator",source="packaging/ForeverCore-source-1.5.0-20261014-000613/src/server/scripts/Commands/cs_character.cpp",verification="database+source",availability="available"},
